import{_ as p,a0 as n,w as o,s as r,ao as d,I as t,x as e,a1 as a,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"记不住 Linux 命令？这三个工具可以帮你 | LCTT x X-CMD","titleTemplate":false,"description":"记不住 Linux 命令？这三个工具可以帮你 | LCTT (201711) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"记不住 Linux 命令？这三个工具可以帮你 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"记不住 Linux 命令？这三个工具可以帮你 | LCTT (201711) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201711/20171020 3 Tools to Help You Remember Linux Commands","title":"记不住 Linux 命令？这三个工具可以帮你","tag":"201711","desc":""},"relativePath":"201711/20171020 3 Tools to Help You Remember Linux Commands.md","filePath":"[post].md"}'),h={name:"201711/20171020 3 Tools to Help You Remember Linux Commands.md"};function u(m,s,c,f,g,b){const i=n("Link");return o(),r("div",null,[s[13]||(s[13]=d(`<h1 id="记不住-linux-命令-这三个工具可以帮你" tabindex="-1">记不住 Linux 命令？这三个工具可以帮你 <a class="header-anchor" href="#记不住-linux-命令-这三个工具可以帮你" aria-label="Permalink to “记不住 Linux 命令？这三个工具可以帮你”">​</a></h1><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/commands-main.jpg?itok=OESH_Evp" alt="apropos" title="apropos"></p><p><em>apropos 工具几乎默认安装在每个 Linux 发行版上，它可以帮你找到你所需的命令。</em></p><p>Linux 桌面从开始的简陋到现在走了很长的路。在我早期使用 Linux 的那段日子里，掌握命令行是最基本的 —— 即使是在桌面版。不过现在变了，很多人可能从没用过命令行。但对于 Linux 系统管理员来说，可不能这样。实际上，对于任何 Linux 管理员（不管是服务器还是桌面），命令行仍是必须的。从管理网络到系统安全，再到应用和系统设定 —— 没有什么工具比命令行更强大。</p><p>但是，实际上……你可以在 Linux 系统里找到_非常多_命令。比如只看 <code>/usr/bin</code> 目录，你就可以找到很多命令执行文件（你可以运行 <code>ls/usr/bin/ | wc -l</code> 看一下你的系统里这个目录下到底有多少命令）。当然，它们并不全是针对用户的执行文件，但是可以让你感受下 Linux 命令数量。在我的 Elementary OS 系统里，目录 <code>/usr/bin</code> 下有 2029 个可执行文件。尽管我只会用到其中的一小部分，我要怎么才能记住这一部分呢？</p><p>幸运的是，你可以使用一些工具和技巧，这样你就不用每天挣扎着去记忆这些命令了。我想和大家分享几个这样的小技巧，希望能让你们能稍微有效地使用命令行（顺便节省点脑力）。</p><p>我们从一个系统内置的工具开始介绍，然后再介绍两个可以安装的非常实用的程序。</p><h3 id="bash-命令历史" tabindex="-1">Bash 命令历史 <a class="header-anchor" href="#bash-命令历史" aria-label="Permalink to “Bash 命令历史”">​</a></h3><p>不管你知不知道，Bash（最流行的 Linux shell）会保留你执行过的命令的历史。想实际操作下看看吗？有两种方式。打开终端窗口然后按向上方向键。你应该可以看到会有命令出现，一个接一个。一旦你找到了想用的命令，不用修改的话，可以直接按 Enter 键执行，或者修改后再按 Enter 键。</p><p>要重新执行（或修改一下再执行）之前运行过的命令，这是一个很好的方式。我经常用这个功能。它不仅仅让我不用去记忆一个命令的所有细节，而且可以不用一遍遍重复地输入同样的命令。</p><p>说到 Bash 的命令历史，如果你执行命令 <code>history</code>，你可以列出你过去执行过的命令列表（图 1）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/commands_1.jpg?itok=2eqm9ii_" alt="Bash 命令历史" title="Bash history"></p><p><em>图 1: 你能找到我敲的命令里的错误吗？</em></p><p>你的 Bash 命令历史保存的历史命令的数量可以在 <code>~/.bashrc</code> 文件里设置。在这个文件里，你可以找到下面两行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HISTSIZE=1000</span></span>
<span class="line"><span></span></span>
<span class="line"><span>HISTFILESIZE=2000</span></span></code></pre></div><p><code>HISTSIZE</code> 是命令历史列表里记录的命令的最大数量，而 <code>HISTFILESIZE</code> 是命令历史文件的最大行数。</p><p>显然，默认情况下，Bash 会记录你的 1000 条历史命令。这已经很多了。有时候，这也被认为是一个安全漏洞。如果你在意的话，你可以随意减小这个数值，在安全性和实用性之间平衡。如果你不希望 Bash 记录你的命令历史，可以将 <code>HISTSIZE</code> 设置为 <code>0</code>。</p><p>如果你修改了 <code>~/.bashrc</code> 文件，记得要登出后再重新登录（否则改动不会生效）。</p><h3 id="apropos" tabindex="-1">apropos <a class="header-anchor" href="#apropos" aria-label="Permalink to “apropos”">​</a></h3><p>这是第一个我要介绍的工具，可以帮助你记忆 Linux 命令。apropos （意即“关于”）能够搜索 Linux 帮助文档来帮你找到你想要的命令。比如说，你不记得你用的发行版用的什么防火墙工具了。你可以输入 <code>apropos “firewall” </code>，然后这个工具会返回相关的命令（图 2）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/commands_2.jpg?itok=MX5zHfet" alt="apropos" title="apropos"></p><p><em>图 2: 你用的什么防火墙？</em></p><p>再假如你需要一个操作目录的命令，但是完全不知道要用哪个呢？输入 <code>apropos “directory”</code> 就可以列出在帮助文档里包含了字符 “directory” 的所有命令（图 3）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/commands_3.jpg?itok=ALEsfP4q" alt="apropos directory" title="apropos directory"></p><p><em>图 3: 可以操作目录的工具有哪些呢？</em></p><p>apropos 工具在几乎所有 Linux 发行版里都会默认安装。</p><h3 id="fish" tabindex="-1">Fish <a class="header-anchor" href="#fish" aria-label="Permalink to “Fish”">​</a></h3><p>还有另一个能帮助你记忆命令的很好的工具。Fish 是 Linux/Unix/Mac OS 的一个命令行 shell，有一些很好用的功能。</p><ul><li>自动推荐</li><li>VGA 颜色</li><li>完美的脚本支持</li><li>基于网页的配置</li><li>帮助文档自动补全</li><li>语法高亮</li><li>以及更多</li></ul><p>自动推荐功能让 fish 非常方便（特别是你想不起来一些命令的时候）。</p><p>你可能觉得挺好，但是 fish 没有被默认安装。对于 Ubuntu（以及它的衍生版），你可以用下面的命令安装：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-add-repository ppa:fish-shell/release-2</span></span>
<span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt install fish</span></span></code></pre></div><p>对于类 CentOS 系统，可以这样安装 fish。用下面的命令增加仓库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo -s</span></span>
<span class="line"><span>cd /etc/yum.repos.d/</span></span>
<span class="line"><span>wget http://download.opensuse.org/repositories/shells:fish:release:2/CentOS_7/shells:fish:release:2.repo</span></span></code></pre></div><p>用下面的命令更新仓库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>yum repolist</span></span>
<span class="line"><span>yum update</span></span></code></pre></div><p>然后用下面的命令安装 fish：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>yum install fish</span></span></code></pre></div><p>fish 用起来可能没你想象的那么直观。记住，fish 是一个 shell，所以在使用命令之前你得先登录进去。在你的终端里，运行命令 fish 然后你就会看到自己已经打开了一个新的 shell（图 4）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/commands_4.jpg?itok=8TBGVhVk" alt="fish shell" title="fish shell"></p><p><em>图 4: fish 的交互式 shell。</em></p><p>在开始输入命令的时候，fish 会自动补齐命令。如果推荐的命令不是你想要的，按下键盘的 Tab 键可以浏览更多选择。如果正好是你想要的，按下键盘的向右键补齐命令，然后按下 Enter 执行。在用完 fish 后，输入 exit 来退出 shell。</p><p>Fish 还可以做更多事情，但是这里只介绍用来帮助你记住命令，自动推荐功能足够了。</p><h3 id="保持学习" tabindex="-1">保持学习 <a class="header-anchor" href="#保持学习" aria-label="Permalink to “保持学习”">​</a></h3><p>Linux 上有太多的命令了。但你也不用记住所有命令。多亏有 Bash 命令历史以及像 apropos 和 fish 这样的工具，你不用消耗太多记忆来回忆那些帮你完成任务的命令。</p><hr>`,46)),t("p",null,[s[1]||(s[1]=e("via: ",-1)),a(i,{href:"https://www.linux.com/learn/intro-to-linux/2017/10/3-tools-help-you-remember-linux-commands"},{default:l(()=>[...s[0]||(s[0]=[e("https://www.linux.com/learn/intro-to-linux/2017/10/3-tools-help-you-remember-linux-commands",-1)])]),_:1})]),t("p",null,[s[5]||(s[5]=e("作者：",-1)),a(i,{href:"https://www.linux.com/users/jlwallen"},{default:l(()=>[...s[2]||(s[2]=[e("JACK WALLEN",-1)])]),_:1}),s[6]||(s[6]=e(" 译者：",-1)),a(i,{href:"https://github.com/zpl1025"},{default:l(()=>[...s[3]||(s[3]=[e("zpl1025",-1)])]),_:1}),s[7]||(s[7]=e(" 校对：",-1)),a(i,{href:"https://github.com/wxy"},{default:l(()=>[...s[4]||(s[4]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=e("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[8]||(s[8]=[e("LCTT",-1)])]),_:1}),s[11]||(s[11]=e(" 原创编译，",-1)),a(i,{href:"https://linux.cn/"},{default:l(()=>[...s[9]||(s[9]=[e("Linux中国",-1)])]),_:1}),s[12]||(s[12]=e(" 荣誉推出",-1))])])}const y=p(h,[["render",u]]);export{L as __pageData,y as default};
